// Get data from previous nodes
const purchaseOrders = $input.first().json;
const replacementOrders = $('Get Replacement Orders Last 90 Days').all();

// Group purchase orders by supplier (plant + storage_location)
const supplierData = {};

// Process purchase orders
for (const order of purchaseOrders) {
  const supplierId = `${order.plant}_${order.storage_location}`;

  if (!supplierData[supplierId]) {
    supplierData[supplierId] = {
      supplier_id: supplierId,
      plant: order.plant,
      storage_location: order.storage_location,
      total_ordered_qty: 0,
      total_received_qty: 0,
      total_deliveries: 0,
      on_time_deliveries: 0,
      quality_incidents: 0
    };
  }

  // Accumulate quantities
  supplierData[supplierId].total_ordered_qty += parseFloat(order.ordered_qty || 0);
  supplierData[supplierId].total_received_qty += parseFloat(order.received_qty || 0);
  supplierData[supplierId].total_deliveries += 1;

  // Check if delivery was on time
  if (order.delivery_date && order.expected_delivery_date) {
    const deliveryDate = new Date(order.delivery_date);
    const expectedDate = new Date(order.expected_delivery_date);
    if (deliveryDate <= expectedDate) {
      supplierData[supplierId].on_time_deliveries += 1;
    }
  }
}

// Process replacement orders for quality incidents
for (const replacement of replacementOrders) {
  const supplierId = `${replacement.plant}_${replacement.storage_location}`;

  if (supplierData[supplierId]) {
    supplierData[supplierId].quality_incidents += 1;
  }
}

// Calculate scores for each supplier
const supplierScores = [];

for (const supplierId in supplierData) {
  const supplier = supplierData[supplierId];

  // Calculate rates
  const fulfillment_rate = supplier.total_ordered_qty > 0 
    ? supplier.total_received_qty / supplier.total_ordered_qty 
    : 0;

  const on_time_rate = supplier.total_deliveries > 0 
    ? supplier.on_time_deliveries / supplier.total_deliveries 
    : 0;

  const quality_incident_rate = supplier.total_deliveries > 0 
    ? supplier.quality_incidents / supplier.total_deliveries 
    : 0;

  // Calculate supplier score using the formula
  // supplier_score = (fulfillment_rate * 0.5) + (on_time_rate * 0.3) - (quality_incident_rate * 0.2)
  // Scale to 0-100
  const raw_score = (fulfillment_rate * 0.5) + (on_time_rate * 0.3) - (quality_incident_rate * 0.2);
  const supplier_score = Math.max(0, Math.min(100, raw_score * 100));

  // Determine tier
  let tier;
  if (supplier_score >= 85) {
    tier = 'RELIABLE';
  } else if (supplier_score >= 70) {
    tier = 'MODERATE';
  } else {
    tier = 'UNRELIABLE';
  }

  supplierScores.push({
    supplier_id: supplier.supplier_id,
    plant: supplier.plant,
    storage_location: supplier.storage_location,
    fulfillment_rate: Math.round(fulfillment_rate * 10000) / 100,
    on_time_rate: Math.round(on_time_rate * 10000) / 100,
    quality_incident_rate: Math.round(quality_incident_rate * 10000) / 100,
    supplier_score: Math.round(supplier_score * 100) / 100,
    tier: tier,
    calculation_date: new Date().toISOString()
  });
}

// Return array of supplier scores
return supplierScores.map(score => ({ json: score }));

// Get data from previous nodes
const purchaseOrders = $('Get Purchase Orders Last 30 Days').all();
const replacementOrders = $('Get Replacement Orders Last 90 Days').all();
const inventoryLevels = $('Get Current Inventory Levels').all();
const supplierScores = $('Calculate Supplier Reliability Scores').all();
const config = $('Workflow Configuration').first().json;

// Get configuration values
const lead_time_days = config.lead_time_days || 14;
const z_score_service_level = config.z_score_service_level || 1.65; // 95% service level

// Helper function to calculate standard deviation
function calculateStdDev(values) {
  if (values.length === 0) return 0;
  const mean = values.reduce((sum, val) => sum + val, 0) / values.length;
  const squaredDiffs = values.map(val => Math.pow(val - mean, 2));
  const variance = squaredDiffs.reduce((sum, val) => sum + val, 0) / values.length;
  return Math.sqrt(variance);
}

// Group replacement orders by product and calculate daily demand
const productDemandData = {};

for (const order of replacementOrders) {
  const materialNumber = order.json.material_number;
  const category = order.json.category;
  const orderedQty = order.json.ordered_qty || 0;
  const orderDate = order.json.order_date;

  if (!productDemandData[materialNumber]) {
    productDemandData[materialNumber] = {
      category: category,
      dailyDemands: [],
      totalQty: 0,
      orders: []
    };
  }

  productDemandData[materialNumber].totalQty += orderedQty;
  productDemandData[materialNumber].orders.push({
    date: orderDate,
    qty: orderedQty
  });
}

// Calculate daily demand by grouping orders by date
for (const materialNumber in productDemandData) {
  const data = productDemandData[materialNumber];
  const dailyDemandMap = {};

  for (const order of data.orders) {
    const dateKey = order.date;
    if (!dailyDemandMap[dateKey]) {
      dailyDemandMap[dateKey] = 0;
    }
    dailyDemandMap[dateKey] += order.qty;
  }

  data.dailyDemands = Object.values(dailyDemandMap);
}

// Group supplier scores by category
const categorySupplierScores = {};

for (const scoreData of supplierScores) {
  const category = scoreData.json.category;
  const supplierScore = scoreData.json.supplier_score || 0;

  if (!categorySupplierScores[category]) {
    categorySupplierScores[category] = [];
  }

  categorySupplierScores[category].push(supplierScore);
}

// Calculate average supplier score per category
const categoryAvgSupplierScore = {};

for (const category in categorySupplierScores) {
  const scores = categorySupplierScores[category];
  const avgScore = scores.reduce((sum, score) => sum + score, 0) / scores.length;
  categoryAvgSupplierScore[category] = avgScore;
}

// Create supplier score lookup by material number
const materialSupplierScore = {};
const materialSupplierTier = {};

for (const scoreData of supplierScores) {
  const materialNumber = scoreData.json.material_number;
  materialSupplierScore[materialNumber] = scoreData.json.supplier_score || 0;
  materialSupplierTier[materialNumber] = scoreData.json.supplier_tier || 'Unknown';
}

// Create inventory lookup
const inventoryLookup = {};

for (const inv of inventoryLevels) {
  const materialNumber = inv.json.material_number;
  inventoryLookup[materialNumber] = inv.json.current_stock || 0;
}

// Calculate buffer stock thresholds for each product
const results = [];

for (const materialNumber in productDemandData) {
  const data = productDemandData[materialNumber];
  const category = data.category;

  // Calculate average daily demand (total qty / 90 days)
  const average_daily_demand = data.totalQty / 90;

  // Calculate demand volatility (standard deviation of daily demands)
  const demand_volatility = calculateStdDev(data.dailyDemands);

  // Get supplier reliability factor for the category
  const supplier_reliability_factor = categoryAvgSupplierScore[category] || 50;

  // Calculate buffer stock using the formula
  const buffer_stock = Math.ceil(
    (average_daily_demand * lead_time_days) + 
    (demand_volatility * z_score_service_level) * 
    (1 + ((100 - supplier_reliability_factor) / 100))
  );

  // Get current stock
  const current_stock = inventoryLookup[materialNumber] || 0;

  // Check if below threshold
  const below_threshold = current_stock < buffer_stock;

  // Get supplier score and tier for this material
  const supplier_score = materialSupplierScore[materialNumber] || 0;
  const supplier_tier = materialSupplierTier[materialNumber] || 'Unknown';

  results.push({
    json: {
      material_number: materialNumber,
      category: category,
      current_stock: current_stock,
      buffer_stock_threshold: buffer_stock,
      below_threshold: below_threshold,
      supplier_score: supplier_score,
      supplier_tier: supplier_tier,
      average_daily_demand: Math.round(average_daily_demand * 100) / 100,
      demand_volatility: Math.round(demand_volatility * 100) / 100,
      supplier_reliability_factor: Math.round(supplier_reliability_factor * 100) / 100
    }
  });
}

return results;

// Generate Purchase Order Draft
const item = $input.item.json;

// Calculate reorder quantity
const reorderQty = item.buffer_stock_threshold - item.current_stock;

// Determine urgency level based on supplier tier
let urgencyLevel;
if (item.supplier_tier === 'UNRELIABLE') {
  urgencyLevel = item.lead_time + 2;
} else {
  urgencyLevel = item.lead_time;
}

// Determine recommended action
let recommendedAction;
if (item.supplier_tier === 'UNRELIABLE') {
  recommendedAction = 'URGENT: Order from alternative supplier or expedite delivery';
} else if (reorderQty > item.buffer_stock_threshold * 0.5) {
  recommendedAction = 'HIGH PRIORITY: Place order immediately';
} else {
  recommendedAction = 'STANDARD: Place order within normal timeframe';
}

// Create purchase order draft
const purchaseOrderDraft = {
  material_number: item.material_number,
  plant: item.plant,
  storage_location: item.storage_location,
  reorder_qty: reorderQty,
  supplier_tier: item.supplier_tier,
  urgency_level: urgencyLevel,
  recommended_action: recommendedAction,
  current_stock: item.current_stock,
  buffer_stock_threshold: item.buffer_stock_threshold,
  lead_time: item.lead_time,
  draft_date: new Date().toISOString()
};

return purchaseOrderDraft;
